CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_roles (user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK (role IN ('contractor', 'freelancer')), active boolean NOT NULL DEFAULT true, PRIMARY KEY (user_id, role));
CREATE TABLE IF NOT EXISTS demands (id uuid PRIMARY KEY, contractor_id uuid NOT NULL REFERENCES users(id), role text NOT NULL, location_point geography(Point, 4326) NOT NULL, address_snapshot text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, value_cents integer NOT NULL CHECK (value_cents >= 0), currency char(3) NOT NULL, acceptance_deadline timestamptz NOT NULL, status text NOT NULL CHECK (status IN ('active', 'reserved', 'cancelled', 'expired', 'completed')), accepted_freelancer_id uuid REFERENCES users(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS demands_location_idx ON demands USING gist (location_point);
CREATE TABLE IF NOT EXISTS freelancer_availability (freelancer_id uuid PRIMARY KEY REFERENCES users(id), status text NOT NULL CHECK (status IN ('online', 'offline')), location_permission text NOT NULL, last_location_point geography(Point, 4326), location_accuracy_meters numeric, last_seen_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS offers (id uuid PRIMARY KEY, demand_id uuid NOT NULL REFERENCES demands(id), freelancer_id uuid NOT NULL REFERENCES users(id), status text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), responded_at timestamptz);
CREATE TABLE IF NOT EXISTS assignments (id uuid PRIMARY KEY, demand_id uuid NOT NULL UNIQUE REFERENCES demands(id), freelancer_id uuid NOT NULL REFERENCES users(id), status text NOT NULL, accepted_at timestamptz NOT NULL, completed_at timestamptz);
CREATE TABLE IF NOT EXISTS microtrainings (id uuid PRIMARY KEY, title text NOT NULL, summary text NOT NULL, content_reference text NOT NULL, role text, route_context text, duration_seconds integer NOT NULL, status text NOT NULL);
CREATE TABLE IF NOT EXISTS outbox_events (id uuid PRIMARY KEY, type text NOT NULL, version integer NOT NULL, aggregate_id uuid NOT NULL, occurred_at timestamptz NOT NULL, payload jsonb NOT NULL, published_at timestamptz);